{
  "title": "Discussion on taxes, domain purchase, app profitability and security concerns",
  "topics": [
    {
      "id": "tax-avoidance",
      "title": "Avoiding large tax penalties with aunt Sveta's help",
      "claims": [
        {
          "text": "Paying aunt Sveta 500 UAH helps avoid a huge main penalty caused by a mis‑marked column in the declaration",
          "evidence": [1]
        },
        {
          "text": "The inspector was corrupt, approving declarations without review for a year and later reprimanded, prompting a full re‑check",
          "evidence": [1]
        },
        {
          "text": "With Sveta’s assistance the author correctly re‑filed and paid about 1000 UAH instead of all fines",
          "evidence": [1]
        }
      ]
    },
    {
      "id": "domain-calculator",
      "title": "Domain purchase and need for a FOP calculator",
      "claims": [
        {
          "text": "The author has not bought a domain yet",
          "evidence": [2]
        },
        {
          "text": "A FOP calculator is needed; once someone buys it, there will be money for the domain",
          "evidence": [3,4]
        },
        {
          "text": "The tax calculation procedure takes about an hour with Excel, at most a day",
          "evidence": [5,6]
        },
        {
          "text": "Quarterly reports must be filed and taxes paid correctly",
          "evidence": [7]
        },
        {
          "text": "The main difficulty is not the calculation itself but correctly matching each column and subtraction",
          "evidence": [8]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a web/Flutter app idea",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS apps",
          "evidence": [11]
        },
        {
          "text": "SEO is poor, no external traffic from social media, no ad revenue, and user retention is almost zero due to paywalls",
          "evidence": [11]
        },
        {
          "text": "Successful projects use fast delivery (< 1 week) and a cross‑platform stack like Flutter, copying popular ideas with minor tweaks",
          "evidence": [12]
        },
        {
          "text": "The author doubts anyone will buy the product, betting on low sales",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience for technical/managerial posts has dropped below 50%",
          "evidence": [18]
        },
        {
          "text": "The calculator works only with a UAH‑based FOP, requiring conversion at the day‑rate of each transaction",
          "evidence": [19]
        },
        {
          "text": "Before proceeding, at least ten people should be willing to pay 299 UAH; otherwise the analysis is pointless",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "security-password",
      "title": "Potential password leak in bundled app",
      "claims": [
        {
          "text": "The source code may contain a hard‑coded password stored in local storage",
          "evidence": [21]
        },
        {
          "text": "The author jokes about many LinkedIn users being able to hack it",
          "evidence": [28]
        },
        {
          "text": "The app is positioned as a local‑first bundle with a password that unlocks full features",
          "evidence": [29,30]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Can the hard‑coded password be found by searching the source code?",
      "evidence": [21]
    }
  ]
}
